import wikiJson from "@/data/generated/wiki.json";
import siteJson from "@/data/generated/site.json";

export type Race = "terran" | "protoss" | "zerg";
export const races: Race[] = ["terran", "protoss", "zerg"];

/** Generated by scripts/wiki/build-wiki-data.js. Run `npm run build:data` after changing mod data. */
export interface ExtensionUnit {
  id: string;
  race: Race;
  icon: string;
  ko: string;
  en: string;
  pairKo: string;
  pairEn: string;
}

export interface MapInfo {
  id: string;
  ko: string;
  en: string;
  key: string;
  terrainKo: string;
  terrainEn: string;
}

export interface WikiVersion {
  id: string;
  status: "current" | "previous" | "archive";
  source: string;
}

export const wiki = wikiJson as unknown as {
  versions: WikiVersion[];
  units: ExtensionUnit[];
  base: unknown[];
};
export const site = siteJson as unknown as { maps: MapInfo[]; extensionUnitCount: number; convenience: { icon: string; title: string; description: string }[] };

export const currentVersion = wiki.versions.find((v) => v.status === "current")!.id;
